class TicTacToe:
    """A class representing a Tic-Tac-Toe game."""

    def __init__(self):
        """Initialize the TicTacToe game."""
        self.board = [[''for _ in range(3)] for _ in range(3)]
        self.current_player = "X"

    def display_board(self):
        """Display the current state of the Tic-Tac-Toe board."""
        for row in self.board:
            print("|".join(row))
            print("-" * 5)

    def is_valid_move(self, row, col):
        """Check if a move is valid (the cell is empty)."""
        return self.board[row][col] ==''

    def make_move(self, row, col):
        """Make a move by the current player."""
        if self.is_valid_move(row, col):
            self.board[row][col] = self.current_player
            if self.check_winner():
                print(f"Player {self.current_player} wins!")
                return True
            if self.check_draw():
                print("It's a draw!")
                return True
            self.switch_player()

    def switch_player(self):
        """Switch the current player."""
        self.current_player = "O" if self.current_player == "X" else "X"

    def check_winner(self):
        """Check if there's a winner."""
        for row in self.board:
            if row[0] == row[1] == row[2]!='':
                return True

        for col in range(3):
            if self.board[0][col] == self.board[1][col] == self.board[2][col]!='':
                return True

        if self.board[0][0] == self.board[1][1] == self.board[2][2]!='':
            return True

        if self.board[0][2] == self.board[1][1] == self.board[2][0]!='':
            return True

        return False

    def check_draw(self):
        """Check if the game is a draw."""
        for row in self.board:
            for cell in row:
                if cell =='':
                    return False
        return True

    def play(self):
        """Play a game of Tic-Tac-Toe."""
        print("Welcome to Tic-Tac-Toe!")
        self.display_board()

        while True:
            row = int(input(f"Player {self.current_player}, enter the row (0-2): "))
            col = int(input(f"Player {self.current_player}, enter the column (0-2): "))

            if 0 <= row < 3 and 0 <= col < 3:
                if self.make_move(row, col):
                    self.display_board()
                    break
                self.display_board()
            else:
                print("Invalid input. Please try again.")


if __name__ == "__main__":
