import ast

def generate_boolean_expression(expression):
    """
    Generates a boolean expression from an algebraic expression.

    Args:
        expression (str): The algebraic expression.

    Returns:
        str: The boolean expression.
    """
    # Parse the algebraic expression into an AST
    tree = ast.parse(expression, mode='eval')

    # Traverse the AST to generate the boolean expression
    def visit_node(node):
        if isinstance(node, ast.Num):
            return str(node.n)
        elif isinstance(node, ast.BinOp):
            left = visit_node(node.left)
            right = visit_node(node.right)
            if isinstance(node.op, ast.Add):
                return f"({left} + {right})"
            elif isinstance(node.op, ast.Sub):
                return f"({left} - {right})"
            elif isinstance(node.op, ast.Mult):
                return f"({left} * {right})"
            elif isinstance(node.op, ast.Div):
                return f"({left} / {right})"
            elif isinstance(node.op, ast.Mod):
                return f"({left} % {right})"
            elif isinstance(node.op, ast.Pow):
                return f"({left} ** {right})"
        elif isinstance(node, ast.UnaryOp):
            operand = visit_node(node.operand)
            if isinstance(node.op, ast.USub):
                return f"-({operand})"
        elif isinstance(node, ast.Name):
            return node.id
        elif isinstance(node, ast.BoolOp):
            values = [visit_node(value) for value in node.values]
            if isinstance(node.op, ast.Or):
                return'or '.join(values)
            elif isinstance(node.op, ast.And):
                return'and '.join(values)
        elif isinstance(node, ast.Compare):
            left = visit_node(node.left)
            comparators = [visit_node(comparator) for comparator in node.comparators]
            if len(comparators) == 1:
                return f"{left} {comparators[0]}"
            else:
                return f"({left} {comparators[0]} {comparators[1]}...)"
        else:
            raise TypeError(f"Unsupported node type: {type(node).__name__}")

    return visit_node(tree.body)

if __name__ == "__main__":
    expression = "2 + 3 * (4 - 1) / (5 % 2)"
    boolean_expression = generate_boolean_expression(expression)
    print(f"The boolean expression for '{expression}' is '{boolean_expression}'")
```

