def get_unique_items(data, unique_items=None):
    """
    Recursively extract all unique items from a nested dictionary.

    Args:
        data (dict): The nested dictionary to extract unique items from.
        unique_items (set, optional): A set to store unique items. If not provided,
            a new set will be created.

    Returns:
        set: A set containing all unique items in the nested dictionary.
    """
    if unique_items is None:
        unique_items = set()

    for key, value in data.items():
        if isinstance(value, dict):
            get_unique_items(value, unique_items)
        else:
            unique_items.add(value)

    return unique_items
